Record IENV (tp : word) (TSD CTX TH sb TOP BOT : Z) (m : mem) : Prop := mkIENV {
  i_tsdi : rw_cells asegs m 1833632 [C1 (b8 1); CB 3 [b8 0; b8 0; b8 0]; C4 (wz 0)];
  i_tp   : rw_cells asegs m (bv_unsigned tp + -88) [C8 (wz TSD)];
  i_tsd  : rw_cells asegs m TSD [C8 (wz CTX)];
  i_ctx  : rw_cells asegs m (CTX + 152) [C8 (wz TH)];
  i_lsan : rw_cells asegs m (bv_unsigned tp + 16) [C4 (wz 0)];
  i_got2 : rw_cells asegs m 0x1b61f8 [C8 (wz 0x10)];
  i_thr  : rw_cells asegs m TH [C8 (wz CTX)];
  i_tid  : rw_cells asegs m (CTX + 8) [C4 (wz 0)];
  i_init : rw_cells asegs m 1838872 [C1 (b8 1)];
  i_afl  : rw_cells asegs m 2368672 [C1 (b8 0); C1 (b8 1); C1 (b8 0)];
  i_can  : rw_cells asegs m 1833628 [C1 (b8 1)];
  i_got  : rw_cells asegs m 1791352 (map (fun v => C8 (wz v)) AGOT_VALS);
  i_shb  : rw_cells asegs m 1835576 [C8 (wz 2147450880)];
  i_hme  : rw_cells asegs m 1838880 [C8 (wz 140737488355327); C8 (wz 0); C8 (wz 0)];
  i_thresh : rw_cells asegs m 2432480 [C8 (wz 0xffffffffffffffff)];
  i_rms  : rw_cells asegs m 1799584 [C8 (wz 1727016)];
  i_fill : rw_cells asegs m 1825380 [C4 (wz 4096); C4 (wz 0); C4 (wz 0xbe)];
  i_part : rw_cells asegs m 1825421 [C1 (b8 1)];
  i_hooks : rw_cells asegs m 2432256 (repeat (C8 (wz 0)) 10);
  i_inst1 : rw_cells asegs m 1821688 [C8 (wz sb)];
  i_inst2 : rw_cells asegs m 1825272 [C8 (wz (2^40)); C2 (wz 16); C2 (wz 2048); C1 (b8 1); CB 3 [b8 0; b8 0; b8 0]];
  (* [comment removed for export] *)
  i_mcs  : rw_cells asegs m 0x1c0f3c [C4 (wz 30)];                 (* [comment removed for export] *)
  i_psc  : rw_cells asegs m 0x24fce0 [C8 (wz 4096)];               (* [comment removed for export] *)
  i_cfu  : rw_cells asegs m (0x251d68 + 34) [C1 (b8 1)];           (* [comment removed for export] *)
  i_stk  : rw_cells asegs m (TH + 8) [C8 (wz TOP); C8 (wz BOT)];   (* [comment removed for export] *)
  i_t40  : rw_cells asegs m (TH + 40) [C1 (b8 0)]
}.

End HCW.


Ltac open_ienv E :=
  destruct E as [Etsdi Etp Etsd Ectx Elsan Egot2 Ethr Etid Einit Eafl Ecan Egot Eshb Ehme Ethresh Erms Efill Epart Ehooks Einst1 Einst2
                 Emcs Epsc Ecfu Estk Et40];
  unfold AGOT_VALS in Egot; cbn [map] in Egot; cbn [repeat] in Ehooks.

